def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height solid lines divide the grid into panels.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, separators):
        out = []
        start = 0
        for p in separators:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    rs = intervals(h, sep_rows)
    cs = intervals(w, sep_cols)
    out = [row[:] for row in grid]

    colors = {x for row in grid for x in row if x != 0}
    for color in colors:
        for ri in range(len(rs) - 1):
            r0, r1 = rs[ri]
            r2, r3 = rs[ri + 1]
            if r1 - r0 != r3 - r2:
                continue
            ph = r1 - r0

            for ci in range(len(cs) - 1):
                c0, c1 = cs[ci]
                c2, c3 = cs[ci + 1]
                if c1 - c0 != c3 - c2:
                    continue
                pw = c1 - c0

                bounds = [
                    (r0, r1, c0, c1), (r0, r1, c2, c3),
                    (r2, r3, c0, c1), (r2, r3, c2, c3)
                ]
                patterns = []
                for a, b, x, y in bounds:
                    patterns.append(tuple(
                        tuple(grid[a + i][x + j] == color for j in range(pw))
                        for i in range(ph)
                    ))

                occupied = [k for k, p in enumerate(patterns) if any(any(row) for row in p)]
                if len(occupied) != 3:
                    continue

                def flip(p, vertical, horizontal):
                    rows = p[::-1] if vertical else p
                    return tuple(tuple(row[::-1]) if horizontal else tuple(row) for row in rows)

                # Infer the canonical top-left panel pattern from each occupied panel.
                canonical = None
                valid = True
                for k in occupied:
                    dr, dc = divmod(k, 2)
                    candidate = flip(patterns[k], bool(dr), bool(dc))
                    if canonical is None:
                        canonical = candidate
                    elif candidate != canonical:
                        valid = False
                        break

                if not valid:
                    continue

                missing = next(k for k in range(4) if k not in occupied)
                dr, dc = divmod(missing, 2)
                fill = flip(canonical, bool(dr), bool(dc))
                a, b, x, y = bounds[missing]
                for i in range(ph):
                    for j in range(pw):
                        if fill[i][j]:
                            out[a + i][x + j] = color

    return out
